A.aGt=s(["\u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0434\u0435\u0442\u0430\u043b\u044c, \u043c\u0430\u0442\u0435\u0440\u0456\u0430\u043b \u0456 \u043d\u0430\u043b\u0430\u0448\u0442\u0443\u0432\u0430\u043d\u043d\u044f slicer.","\u041e\u0447\u0438\u0441\u0442\u0456\u0442\u044c, \u0437\u043c\u0456\u043d\u0456\u0442\u044c \u043e\u0434\u0438\u043d \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440 \u0456 \u0437\u0440\u043e\u0431\u0456\u0442\u044c \u043a\u043e\u0440\u043e\u0442\u043a\u0438\u0439 \u0442\u0435\u0441\u0442.","\u0417\u0430\u043b\u0438\u0448\u0430\u0439\u0442\u0435 \u0437\u043c\u0456\u043d\u0443 \u043b\u0438\u0448\u0435 \u044f\u043a\u0449\u043e \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043a\u0440\u0430\u0449\u0438\u0439."],t.s)
A.aH9=s(["\u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0432\u0430\u043d\u043d\u0443, FEP, \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0443 \u0442\u0430 \u0435\u043a\u0441\u043f\u043e\u0437\u0438\u0446\u0456\u044e.","\u0412\u0438\u0434\u0430\u043b\u0456\u0442\u044c \u0437\u0430\u043b\u0438\u0448\u043a\u0438 \u0439 \u0440\u0435\u0433\u0443\u043b\u044e\u0439\u0442\u0435 \u043c\u0430\u043b\u0438\u043c\u0438 \u043a\u0440\u043e\u043a\u0430\u043c\u0438.","\u041f\u0435\u0440\u0435\u0434 \u0434\u043e\u0432\u0433\u0438\u043c \u0434\u0440\u0443\u043a\u043e\u043c \u043f\u0440\u043e\u0442\u0435\u0441\u0442\u0443\u0439\u0442\u0435 \u043c\u0430\u043b\u0443 \u0434\u0435\u0442\u0430\u043b\u044c."],t.s)
