A.af_=s(["Nettoyez le plateau et chauffez-le \xe0 la temp\xe9rature du mat\xe9riau.","Lancez le nivellement et v\xe9rifiez l\u2019offset Z avec un test.","La ligne doit \xeatre l\xe9g\xe8rement \xe9cras\xe9e, sans racler le plateau."],t.s)
A.aTe=new B.am("filament","CALIBRAGE","Premi\xe8re couche stable","R\xe9glez plateau, buse et offset Z avant d\u2019imprimer.",A.af_,"Si la buse touche le plateau, relevez doucement l\u2019offset Z.",null)
A.aF_=s(["S\xe9chez le filament s\u2019il cr\xe9pite, bulle ou laisse des fils.","Rangez les bobines dans une bo\xeete s\xe8che avec gel de silice.","Faites une tour de temp\xe9rature et ajustez la r\xe9traction."],t.s)
A.aTl=new B.am("filament","QUALIT\xc9","Trop de fils","V\xe9rifiez humidit\xe9, temp\xe9rature et r\xe9traction.",A.aF_,"Chaque mat\xe9riau se s\xe8che \xe0 une temp\xe9rature diff\xe9rente.","dryer")
A.aFk=s(["Nettoyez graisse et poussi\xe8re du plateau.","Utilisez un brim pour les petites bases ou les angles.","Appliquez une fine couche d\u2019adh\xe9sif 3D si le plateau le permet."],t.s)
A.aTi=new B.am("filament","ADH\xc9RENCE","La pi\xe8ce se d\xe9colle","Am\xe9liorez l\u2019adh\xe9rence sans ab\xeemer la surface.",A.aFk,"Laissez refroidir le plateau avant d\u2019utiliser des outils.","adhesive")
A.aEJ=s(["Portez des gants nitrile avant de toucher la r\xe9sine liquide.","Travaillez dans un lieu ventil\xe9.","Durcissez supports et d\xe9chets avant de les jeter."],t.s)
A.aT7=new B.am("resin","S\xc9CURIT\xc9","Manipulation s\xfbre de la r\xe9sine","Prot\xe9gez peau, yeux et ventilation.",A.aEJ,"Ne versez pas de r\xe9sine liquide ni d\u2019alcool contamin\xe9 au drain.",null)
A.aGj=s(["Agitez la bouteille avant de remplir le bac.","Imprimez un petit test avec votre r\xe9sine.","Ajustez l\u2019exposition par petits pas."],t.s)
A.aSm=new B.am("resin","CALIBRAGE","Test d\u2019exposition","R\xe9glez l\u2019exposition avant les longues impressions.",A.aGj,"Changez un seul r\xe9glage \xe0 la fois.",null)
A.aFQ=s(["Laissez \xe9goutter la pi\xe8ce au-dessus du bac.","Lavez jusqu\u2019\xe0 retirer la r\xe9sine de surface.","S\xe9chez puis durcissez par courtes sessions."],t.s)
A.aSt=new B.am("resin","POST-TRAITEMENT","Lavage et durcissement","\xc9vitez les pi\xe8ces collantes ou fragiles.",A.aFQ,"Un durcissement excessif peut fragiliser les pi\xe8ces fines.",null)
A.aGP=s([A.aTe,A.aTl,A.aTi,A.aT7,A.aSm,A.aSt],t.Q)
A.aq5=s(["Pulisci il piano e scaldalo alla temperatura del materiale.","Esegui il livellamento e controlla l\u2019offset Z con un test.","La linea deve essere leggermente schiacciata, senza graffiare."],t.s)
A.aSz=new B.am("filament","CALIBRAZIONE","Primo layer stabile","Regola piano, ugello e offset Z prima di stampare.",A.aq5,"Se l\u2019ugello tocca il piano, alza gradualmente l\u2019offset Z.",null)
A.aGy=s(["Asciuga il filamento se scoppietta, fa bolle o lascia fili.","Conserva le bobine in una scatola asciutta con gel di silice.","Stampa una torre temperatura e regola la retrazione."],t.s)
A.aTE=new B.am("filament","QUALIT\xc0","Troppi fili","Controlla umidit\xe0, temperatura e retrazione.",A.aGy,"Ogni materiale richiede una temperatura di asciugatura diversa.","dryer")
A.aEf=s(["Rimuovi grasso e polvere dal piano.","Usa un brim per basi piccole o angoli vivi.","Applica un sottile strato di adesivo 3D se compatibile."],t.s)
