A.aHN=s(["Reinigen Sie das Bett und heizen Sie es auf Materialtemperatur.","F\xfchren Sie die Nivellierung aus und pr\xfcfen Sie den Z-Offset.","Die Linie soll leicht gedr\xfcckt sein, ohne zu kratzen."],t.s)
A.aTd=new B.am("filament","KALIBRIERUNG","Stabile erste Schicht","Stellen Sie Bett, D\xfcse und Z-Offset vor dem Drucken ein.",A.aHN,"Wenn die D\xfcse das Bett ber\xfchrt, erh\xf6hen Sie den Z-Offset langsam.",null)
A.aEe=s(["Trocknen Sie Filament, wenn es knackt, blubbert oder F\xe4den zieht.","Lagern Sie Spulen trocken mit Silicagel.","Drucken Sie einen Temperaturturm und passen Sie den R\xfcckzug an."],t.s)
A.aSR=new B.am("filament","QUALIT\xc4T","Zu viele F\xe4den","Pr\xfcfen Sie Feuchtigkeit, Temperatur und R\xfcckzug.",A.aEe,"Jedes Material braucht eine andere Trocknungstemperatur.","dryer")
A.aEL=s(["Entfernen Sie Fett und Staub vom Druckbett.","Nutzen Sie Brim bei kleinen Fl\xe4chen oder scharfen Ecken.","Tragen Sie d\xfcnn 3D-Druckkleber auf, wenn die Oberfl\xe4che es erlaubt."],t.s)
A.aTb=new B.am("filament","HAFTUNG","Teil l\xf6st sich vom Bett","Verbessern Sie die Haftung ohne die Oberfl\xe4che zu besch\xe4digen.",A.aEL,"Lassen Sie das Bett abk\xfchlen, bevor Sie Werkzeuge verwenden.","adhesive")
A.aFr=s(["Tragen Sie Nitrilhandschuhe bei fl\xfcssigem Harz.","Arbeiten Sie in einem gut bel\xfcfteten Bereich.","H\xe4rten Sie St\xfctzen und Abf\xe4lle vor der Entsorgung aus."],t.s)
A.aSy=new B.am("resin","SICHERHEIT","Sicherer Umgang mit Harz","Sch\xfctzen Sie Haut, Augen und Bel\xfcftung.",A.aFr,"Gie\xdfen Sie Harz oder verunreinigten Alkohol nicht in den Abfluss.",null)
A.aIa=s(["Sch\xfctteln Sie die Harzflasche vor dem Bef\xfcllen.","Drucken Sie einen kleinen Test mit Ihrer Schichth\xf6he.","\xc4ndern Sie die Belichtung in kleinen Schritten."],t.s)
A.aTH=new B.am("resin","KALIBRIERUNG","Belichtungstest","Stellen Sie die Belichtung vor langen Drucken ein.",A.aIa,"\xc4ndern Sie immer nur eine Einstellung.",null)
A.aFx=s(["Lassen Sie das Teil \xfcber dem Tank abtropfen.","Waschen Sie, bis kein Oberfl\xe4chenharz mehr bleibt.","Trocknen Sie und h\xe4rten Sie in kurzen Runden."],t.s)
A.aTx=new B.am("resin","NACHBEARBEITUNG","Waschen und H\xe4rten","Vermeiden Sie klebrige oder spr\xf6de Teile.",A.aFx,"Zu langes H\xe4rten kann d\xfcnne Teile spr\xf6de machen.",null)
A.aG2=s([A.aTd,A.aSR,A.aTb,A.aSy,A.aTH,A.aTx],t.Q)
