A.aSp=new B.am("filament","CALIBRA\xc7\xc3O","Primeira camada est\xe1vel","Ajuste mesa, bico e offset Z antes de imprimir.",A.aIq,"Se o bico tocar a mesa, suba o offset Z aos poucos.",null)
A.akt=s(["Seque o filamento se estalar, borbulhar ou deixar fios.","Guarde bobinas em local seco com s\xedlica gel.","Fa\xe7a uma torre de temperatura e ajuste a retra\xe7\xe3o."],t.s)
A.aSE=new B.am("filament","QUALIDADE","Muitos fiapos","Verifique umidade, temperatura e retra\xe7\xe3o.",A.akt,"Cada material seca em uma temperatura diferente.","dryer")
