A.aTf=new B.am("filament","ADER\xcaNCIA","A pe\xe7a descola da mesa","Melhore a ader\xeancia sem danificar a superf\xedcie.",A.aEI,"Espere a mesa esfriar antes de usar ferramentas.","adhesive")
A.aDW=s(["Use luvas de nitrilo antes de tocar resina l\xedquida.","Trabalhe em local ventilado.","Cure suportes e res\xedduos antes de descartar."],t.s)
A.aTU=new B.am("resin","SEGURAN\xc7A","Manuseio seguro de resina","Proteja pele, olhos e ventila\xe7\xe3o.",A.aDW,"N\xe3o jogue resina ou \xe1lcool contaminado no ralo.",null)
