A.aIv=s(["Deixe a pe\xe7a escorrer sobre o tanque.","Lave at\xe9 remover a resina da superf\xedcie.","Seque e cure em sess\xf5es curtas, girando a pe\xe7a."],t.s)
A.aT6=new B.am("resin","P\xd3S-PROCESSO","Lavagem e cura","Evite pe\xe7as pegajosas ou fr\xe1geis.",A.aIv,"Cura excessiva pode deixar pe\xe7as finas quebradi\xe7as.",null)
A.aFq=s([A.aSp,A.aSE,A.aTf,A.aTU,A.aSU,A.aT6],t.Q)
A.aG0=s(["\u30d9\u30c3\u30c9\u3092\u6e05\u6383\u3057\u3066\u6750\u6599\u6e29\u5ea6\u307e\u3067\u52a0\u71b1\u3057\u307e\u3059\u3002","\u30ec\u30d9\u30ea\u30f3\u30b0\u3092\u884c\u3044\u3001\u521d\u5c64\u30c6\u30b9\u30c8\u3067Z\u30aa\u30d5\u30bb\u30c3\u30c8\u3092\u78ba\u8a8d\u3057\u307e\u3059\u3002","\u7dda\u306f\u5c11\u3057\u62bc\u3057\u3064\u3076\u3055\u308c\u3001\u64e6\u3089\u306a\u3044\u72b6\u614b\u304c\u7406\u60f3\u3067\u3059\u3002"],t.s)
