A.aTR=new B.am("filament","\u041a\u0410\u041b\u0406\u0411\u0420\u0423\u0412\u0410\u041d\u041d\u042f","\u0421\u0442\u0430\u0431\u0456\u043b\u044c\u043d\u0438\u0439 \u043f\u0435\u0440\u0448\u0438\u0439 \u0448\u0430\u0440","\u041d\u0430\u043b\u0430\u0448\u0442\u0443\u0439\u0442\u0435 \u0441\u0442\u0456\u043b, \u0441\u043e\u043f\u043b\u043e \u0439 Z-offset \u043f\u0435\u0440\u0435\u0434 \u0434\u0440\u0443\u043a\u043e\u043c.",A.aE2,"\u042f\u043a\u0449\u043e \u0441\u043e\u043f\u043b\u043e \u0442\u043e\u0440\u043a\u0430\u0454\u0442\u044c\u0441\u044f \u0441\u0442\u043e\u043b\u0430, \u043f\u043e\u0441\u0442\u0443\u043f\u043e\u0432\u043e \u043f\u0456\u0434\u043d\u0456\u043c\u0456\u0442\u044c Z-offset.",null)
A.aEY=s(["\u0412\u0438\u0441\u0443\u0448\u0456\u0442\u044c \u0444\u0456\u043b\u0430\u043c\u0435\u043d\u0442, \u044f\u043a\u0449\u043e \u0432\u0456\u043d \u0442\u0440\u0456\u0449\u0438\u0442\u044c, \u043f\u0443\u0437\u0438\u0440\u0438\u0442\u044c\u0441\u044f \u0430\u0431\u043e \u0442\u044f\u0433\u043d\u0435 \u043d\u0438\u0442\u043a\u0438.","\u0417\u0431\u0435\u0440\u0456\u0433\u0430\u0439\u0442\u0435 \u043a\u043e\u0442\u0443\u0448\u043a\u0438 \u0441\u0443\u0445\u043e \u0456\u0437 \u0441\u0438\u043b\u0456\u043a\u0430\u0433\u0435\u043b\u0435\u043c.","\u041d\u0430\u0434\u0440\u0443\u043a\u0443\u0439\u0442\u0435 \u0442\u0435\u043c\u043f\u0435\u0440\u0430\u0442\u0443\u0440\u043d\u0443 \u0431\u0430\u0448\u0442\u0443 \u0456 \u043d\u0430\u043b\u0430\u0448\u0442\u0443\u0439\u0442\u0435 \u0440\u0435\u0442\u0440\u0430\u043a\u0442."],t.s)
A.aTz=new B.am("filament","\u042f\u041a\u0406\u0421\u0422\u042c","\u0417\u0430\u0431\u0430\u0433\u0430\u0442\u043e \u043d\u0438\u0442\u043e\u043a","\u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0432\u043e\u043b\u043e\u0433\u0443, \u0442\u0435\u043c\u043f\u0435\u0440\u0430\u0442\u0443\u0440\u0443 \u0456 \u0440\u0435\u0442\u0440\u0430\u043a\u0442.",A.aEY,"\u041a\u043e\u0436\u0435\u043d \u043c\u0430\u0442\u0435\u0440\u0456\u0430\u043b \u0441\u0443\u0448\u0438\u0442\u044c\u0441\u044f \u043f\u0440\u0438 \u0440\u0456\u0437\u043d\u0456\u0439 \u0442\u0435\u043c\u043f\u0435\u0440\u0430\u0442\u0443\u0440\u0456.","dryer")
